  ('27464386063', 1, 'Promedio 4 / 5. • LALI @ RIVER (sep-26) – Acomodador: 26/9: 4 [prom 4.00] • ALE SANZ 2: Buena actitud • BAD BUNNY 2: Buena atencion al publico, proactivo, con ganas y atento a las indicaciones.'),
  ('27472776563', 1, '• HIPÓDROMO SAN ISIDRO - STRAY KIDS/JAMIROQUAI (sep-26) – Acomodadores: 15/09: 5; 17/09: 5 [prom 5.00]'),
  ('27955529222', 1, '• PÁDEL SENIOR PQ. ROCA (sep-26) – Acomodador: 13/9: 4.75 [prom 4.75] • ALE SANZ 2: Resolutiva y compañera.'),
  ('27353637571', 1, '• ALE SANZ 2: Maravillosa! Resuelve y es buena compañera!'),
  ('27473430709', 2, 'Promedio 4.75 / 5. • LALI @ RIVER (sep-26) – Acomodador: 26/9: 4.75 – Atenta y resolutiva [prom 4.75] • ACRED ULTRA: Hay que estarle bastante encima. Funciona bien para acreditar seguridad • ACRED ALE SANZ: Para funciones basicas como op va bien. Falta iniciativa • ACRED LOLLAPALOOZA: Activo/a y con buena onda para trabajar. Se notó predisposición y compromiso.'),
  ('23448701484', 1, '• LALI @ RIVER (sep-26) – Supervisión (feedback Lautaro Roibal, 28/9): Posicionó a su gente rápido; fue la única de su equipo que llegó bien de tiempo y después ayudó al resto • RRHH OPERACIONES: Quiere probar: Supervisor: gestión de liderazgo, trabajo en equipos, comunicación efectiva — Buen manejo de equipo, ordenada y buenas respuestas. No tiene interes en crecer en este rubro'),
  ('23425045539', 1, '• ACRED ULTRA: lo tuvimos encargándose de los parkings y estuvo muy bien. Consulto todo y estuvo súper dispuesto a realizar bien sus tareas. Sin embargo no lo vimos bien como trabaja de operador normal. • ACRED LOLLAPALOOZA: Operador con poca experiencia. Debe mejorar su nivel de atención a las indicaciones de los encargados, así como sus modos de interacción con proveedores. Asimismo, es importante reforzar el cumplimiento de los horarios establecidos.'),
  ('23947869094', 1, 'Promedio 4 / 5. • AC/DC 3: Muy bien • AC/DC 1: Muy bien • ALE SANZ 1: Muy bien • AIRBAG (jun-26): Trabajó muy bien, no tuvo problemas en el sector, no sobresale [puntaje 4.0]'),
  ('27402270069', 1, '• ALE SANZ 2: Proactiva y atenta a los detalles'),
  ('27410780726', 1, 'Promedio 4.25 / 5. • LALI @ RIVER (sep-26) – Acomodador: 26/9: 4.25 [prom 4.25] • AC/DC 3: Muy bien • ALE SANZ 1: Muy bien • ALE SANZ 2: Buena actitud y proactiva en todo momento'),
  ('27477527219', 1, 'Promedio 4.5 / 5. • LALI @ RIVER (sep-26) – Acomodador: 26/9: 5 – Muy buena predisposicion [prom 5.00] • AC/DC 3: Muy bien • ALE SANZ 2: Buena actitud y muy amable. • AIRBAG (jun-26): Trabajó muy bien, no tuvo problemas en el sector, no sobresale [puntaje 4.0]'),
  ('27429347845', 1, '• ALE SANZ 2: Prolija y buena actitud para resolver situaciones complejas.'),
  ('27427202440', 3, '• AC/DC 3 ⚠: Mala predisposición. No bune flujo de trabajo.'),
  ('27455189212', 1, '• ROAD SHOW COLAPINTO: Se sentaba en las barandas y usó el celular • AC/DC 3: Muy bien • AC/DC 1: Muy bien'),
  ('20457479027', 2, '• PÁDEL SENIOR PQ. ROCA (sep-26) – Orientador: 13/9: 4.5; 14/9: 5 – Desempeño destacable al enfrentar distintas tareas al simultáneo; 19/9: 4.25 – Se va de su puesto de trabajo pese a las indicaciones del supervisor [prom 4.58]'),
  ('27476646141', 1, '• ALE SANZ 2: Buena actitud y muy amable.'),
  ('27411313358', 1, '• ALE SANZ 1: Me dijo que era su primer evento, excelente. Compañera, atenta y proactiva'),
  ('27958906833', 1, '• ROAD SHOW COLAPINTO: Trabajo bien, tuvo buen trato con la gente • ALE SANZ 2: Proactiva. Se ofreció para estar en derivación y lo hizo muy bien'),
  ('27421015118', 1, 'Promedio 4 / 5. • ALE SANZ 2: Súper atenta y proactiva • AIRBAG (jun-26): Trabajó muy bien, no tuvo problemas en el sector, no sobresale [puntaje 4.0]'),
  ('27456265907', 1, '• ALE SANZ 2: muy buen desempeño'),
  ('27442623878', 1, 'Promedio 4 / 5. • AIRBAG (jun-26): Trabajó muy bien, no tuvo problemas en el sector, no sobresale [puntaje 4.0]'),
  ('27453543485', 1, '• ACRED BUENA VIBRA: Sobresalio en el desempeño como operadora, tiene muy buen potencial en el área. A destacar siempre tiene muy buena predisposición. • ACRED AC/DC: My predispuesta a todas las tareas, siempre ofrece ayuda y aprende rapido. Muy buena operadora'),
  ('23410697904', 1, '• AC/DC 3: muy buena acomodadora, predispuesta • AC/DC 2: Muy bien • AC/DC 1: Muy bien • ALE SANZ 1: Atenta y resolutiva • ALE SANZ 2: Simpática, amable y proactiva.'),
  ('20962308636', 1, '• AC/DC 3: Trabajo muy bien, siempre cumple y más • AC/DC 2: Trabaja bien, muy activo y dispuesto a ayudar en lo que corresponda. Es extrovertido y eso ayuda a sus compañeros a desenvolverse • AC/DC 1: Muy bien • ALE SANZ 2: Bien • BUENA VIBRA: Buen desempeño'),
  ('27476845888', 1, '• HIPÓDROMO SAN ISIDRO - STRAY KIDS/JAMIROQUAI (sep-26) – Acomodadores: 17/09: 5 [prom 5.00] • AC/DC 3: Muy bien, muy activa y resolutiva, cumplió el rol asignado más que bien, al principio fue medio tímida pero una vez acomodo a las primeras personas, acompañaba constantemente a la gente desorientada y los ayudaba si los notaba desorientados. Buen perfil para operador de acreditaciones.'),
  ('27398467855', 1, '• HIPÓDROMO SAN ISIDRO - STRAY KIDS/JAMIROQUAI (sep-26) – Acomodadores: 15/09: 4; 17/09: 4 [prom 4.00]'),
  ('23457811144', 1, 'Promedio 5 / 5. • LALI @ RIVER (sep-26) – Acomodador: 26/9: 5 [prom 5.00]'),
  ('27460294628', 1, '• LALI @ RIVER (sep-26) – Supervisión (feedback Lautaro Roibal, 28/9): Su grupo ya tenía a la gente posicionada antes de que Lautaro preguntara; sin observaciones'),
  ('27458237145', 1, '• ACRED BAD BUNNY: Destaco por ser: proactivos, dispuestos a ayudar, y atentos. • ACRED LOLLAPALOOZA: Mostró una excelente predisposición para aprender y asumir distintas tareas. En el puesto de operador de cargas se desempeñó con soltura y sin dificultades. Se encuentra en condiciones de proyectarse hacia posiciones de mayor responsabilidad. //////// Ordenada y clara al momento de trabajar. Se adaptó bien al ritmo y acompañó bien al equipo. • RRHH OPERACIONES: Quiere probar: Runner: relación con cliente, soporte logístico, asistencia general — Operadora fuerte, manejó los buses y super respon…'),
  ('27470087019', 1, 'Promedio 4 / 5. • AC/DC 3: Trabajó super bien y muy predispuesta • AIRBAG (jun-26): Trabajo bien y cumplio su puesto sin problemas. [puntaje 4.0]'),
  ('27476538853', 2, 'Promedio 3.25 / 5. • LALI @ RIVER (sep-26) – Acomodador: 26/9: 3.25 – medio apagada, no estaba tan proactiva con la gente [prom 3.25]')
) as v(doc, sem, coment)
join public.personas p
  on upper(regexp_replace(coalesce(p.cuit, ''), '[^0-9A-Za-z]', '', 'g')) = v.doc
where coalesce(p.out_flag, false) = false
  -- Si ya se importó antes, no vuelve a cargarlo.
  and not exists (
    select 1 from public.feedbacks f
    where f.persona_id = p.id and f.supervisor_nombre = 'Planilla de feedbacks'
  );

